"""The CLI reference at the end of SKILL.md, generated from the commands' help so that it
cannot drift from them. `make skill` writes it."""

from pathlib import Path

import click

import agent_sessions.cli
import agent_sessions.skill
from agent_tools.cli import cli

SKILL = Path(__file__).parents[2] / "SKILL.md"
MARKER = (
    "<!-- Everything below is generated by `make skill` from the commands' help. -->\n"
)


def reference() -> str:
    ctx = click.Context(
        cli, info_name="agent", terminal_width=100, max_content_width=100
    )
    sessions = agent_sessions.skill.commands(agent_sessions.cli.main, "agent sessions")
    lines = [
        "",
        "## `agent` commands",
        "",
        "```",
        *cli.get_help(ctx).splitlines(),
        "```",
        "",
        "## `agent sessions` commands",
        "",
        *sessions,
    ]
    return "\n".join(line.rstrip() for line in lines).rstrip() + "\n"


def write() -> None:
    text = SKILL.read_text()
    manual = text.split(MARKER, 1)[0].rstrip("\n") + "\n\n"
    SKILL.write_text(manual + MARKER + reference())


if __name__ == "__main__":
    write()
